begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(12);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)values('00000000-0000-0000-0000-000000000000','20000000-0000-4000-8000-000000000001','authenticated','authenticated','m2@example.test',crypt('password',gen_salt('bf')),now(),'{}','{"username":"MilestoneTwo"}',now(),now(),'','','','');
reset role;update public.properties set storage_capacity=200 where player_id='20000000-0000-4000-8000-000000000001';update public.player_resources set amount=30 where player_id='20000000-0000-4000-8000-000000000001'and resource in('wood','stone','iron','food');update public.player_economy set coins=1000 where player_id='20000000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
select public.set_current_location('forest');select lives_ok($$select public.execute_job('lumberjack','20000000-0000-4000-8000-000000000011')$$,'lumberjack job works');select is((select energy from public.residents where player_id=auth.uid()),90,'job consumes Energy');select is((select amount from public.player_resources where player_id=auth.uid()and resource='wood'),38,'job grants Wood');
select lives_ok($$select public.craft_item('planks','20000000-0000-4000-8000-000000000012')$$,'craft works');select is((select amount from public.player_resources where player_id=auth.uid()and resource='planks'),2,'craft output persists');
reset role;update public.player_resources set amount=1 where player_id='20000000-0000-4000-8000-000000000001'and resource='meals';update public.residents set energy=50 where player_id='20000000-0000-4000-8000-000000000001';set local role authenticated;select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.use_meal('20000000-0000-4000-8000-000000000013')$$,'Meal use works');select is((select energy from public.residents where player_id=auth.uid()),70,'Meal restores Energy');select is((select amount from public.player_resources where player_id=auth.uid()and resource='meals'),0,'Meal is consumed');
select throws_like($$select public.craft_item('invalid','20000000-0000-4000-8000-000000000014')$$,'%Unsupported%','invalid recipe rejected');select throws_like($$select public.execute_job('farmer','20000000-0000-4000-8000-000000000015')$$,'%correct job location%','location is authoritative');
select public.execute_job('lumberjack','20000000-0000-4000-8000-000000000011');select is((select jobs_completed from public.residents where player_id=auth.uid()),1,'job replay is idempotent');select is((select count(distinct reference_id)from public.economy_transactions where player_id=auth.uid()and transaction_type like 'JOB%'),1::bigint,'job uses one ledger reference');select * from finish();rollback;
